mapper.select:
select notes.id, notes.course_id, notes.content, notes.file_name, notes.time_added, notes.time_updated, courses.term_id, terms.start_date from notes left join courses on notes.course_id = courses.id left join terms on courses.term_id = terms.id where 1 = 1
and courses.term_id = #{termId}
and notes.course_id = #{courseId}
and date(notes.time_added) >= date(#{start})
and date(notes.time_added) <= date(#{end})
order by notes.time_added desc

mapper.update:
update notes
course_id = #{cid}, content = #{content}, deletable = #{param5},
file_name = #{fn}
where id = #{id}
